// Query FriBidi's current debug status and record it for downstream stubs.
// No inputs; relies on globally linked FriBidi.
int status = fribidi_debug_status();
// Save raw status and a boolean interpretation for potential later use.
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_status_raw", status);
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_status_bool", status != 0);
// No assumptions/assertions about semantics beyond that it returns an int.
// No outputs to return; only global state updated.

// Generate a fuzzed integer to set the debug state. No specific range is documented,
// so pass through the fuzzed int as-is.
int desired_state = (int)(*FUZZ_PARAM(unsigned int));
// Apply the new debug setting; capture return for observability but do not assert semantics.
int prev_or_status = fribidi_set_debug(desired_state);
// Optionally observe the new status via the query API to increase coverage and track state.
int observed = fribidi_debug_status();
// Track both what we asked for and what we observed, without assuming a strict relation.
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_set_last_input", desired_state);
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_set_ret", prev_or_status);
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_status_after_set_raw", observed);
FUZZ_SET_ATTR_INT_GLOBAL("fribidi_debug_status_after_set_bool", observed != 0);
// No outputs to return; global state updated for other stubs.

// Generate a valid Unicode scalar value for FriBidiChar (U+0000..U+10FFFF, excluding surrogates)
unsigned int raw = *FUZZ_PARAM(unsigned int);
FriBidiChar ch = (FriBidiChar)(raw % 0x110000);
if (ch >= 0xD800 && ch <= 0xDFFF) {
    ch = 0xFFFD; // remap surrogate range to the replacement character
}
// Call target: pure function, no side-effects
volatile FriBidiJoiningType jt = fribidi_get_joining_type(ch);
(void)jt; // suppress unused warning
// Validation: We ensured input is a valid scalar; function has no side effects and returns a value. No further constraints documented.

// Generate a FriBidiJoiningType value (public type is uint8_t in normal builds)
unsigned int r = *FUZZ_PARAM(unsigned int);
FriBidiJoiningType j = (FriBidiJoiningType)(r & 0xFF);

// Call target to obtain a static, library-owned string; do not modify or free
const char *name = fribidi_get_joining_type_name(j);
(void)name; // We don't assert on contents; behavior for out-of-range values is unspecified
// Validation: Input constrained to type width; returned pointer is used read-only and not freed.

// Determine desired length (cap at 256 to stay within small stack buffers)
unsigned int want = *FUZZ_PARAM(unsigned int) % 257; // 0..256
FriBidiStrIndex len = (FriBidiStrIndex)want;

// Use a fuzzed byte string as entropy to populate codepoints, respecting the FUZZ_PARAM loop constraint
std::string bytes = FUZZ_PARAM_STR();
size_t avail_cp = bytes.size() / 4; // 4 bytes per codepoint from the fuzzed string
if (avail_cp < (size_t)len) {
    // Reduce len so we only read within the provided fuzz buffer
    len = (FriBidiStrIndex)avail_cp;
    if (len > 256) len = 256;
}

// Prepare input/output buffers on stack; always pass valid pointers regardless of len
FriBidiChar str_buf[256];
FriBidiJoiningType jtypes_buf[256];

// Populate input codepoints from 4-byte chunks; normalize to valid Unicode scalars (exclude surrogates)
for (FriBidiStrIndex i = 0; i < len; ++i) {
    size_t off = (size_t)i * 4;
    uint32_t v = 0;
    if (off + 3 < bytes.size()) {
        // Little-endian assembly from 4 bytes
        v  = (uint8_t)bytes[off + 0];
        v |= (uint32_t)((uint8_t)bytes[off + 1]) << 8;
        v |= (uint32_t)((uint8_t)bytes[off + 2]) << 16;
        v |= (uint32_t)((uint8_t)bytes[off + 3]) << 24;
    }
    v %= 0x110000u; // U+0000..U+10FFFF
    if (v >= 0xD800u && v <= 0xDFFFu) v = 0xFFFDu; // remap surrogate range
    str_buf[i] = (FriBidiChar)v;
}

// Invoke target; API requires valid pointers when len > 0, which we satisfy
fribidi_get_joining_types((const FriBidiChar*)str_buf, len, (FriBidiJoiningType*)jtypes_buf);

// Property-based validation: for a few indices, per-element function must match
if (len > 0) {
    FriBidiStrIndex i0 = 0;
    FriBidiStrIndex i1 = (len > 1) ? (len / 2) : 0;
    FriBidiStrIndex i2 = (len > 2) ? (len - 1) : 0;

    FriBidiJoiningType jt0_a = jtypes_buf[i0];
    FriBidiJoiningType jt0_b = fribidi_get_joining_type(str_buf[i0]);
    FUZZ_ASSERT(jt0_a == jt0_b, "Mismatch at index 0");

    if (len > 1) {
        FriBidiJoiningType jt1_a = jtypes_buf[i1];
        FriBidiJoiningType jt1_b = fribidi_get_joining_type(str_buf[i1]);
        FUZZ_ASSERT(jt1_a == jt1_b, "Mismatch at middle index");
    }
    if (len > 2) {
        FriBidiJoiningType jt2_a = jtypes_buf[i2];
        FriBidiJoiningType jt2_b = fribidi_get_joining_type(str_buf[i2]);
        FUZZ_ASSERT(jt2_a == jt2_b, "Mismatch at last index");
    }
}

// Validation summary: We cap length to available fuzz bytes and 256, sanitize codepoints, pass valid buffers, and assert equivalence with per-char API.

// Generate a reasonable length for the test run (keep small for performance)
FriBidiStrIndex len = (FriBidiStrIndex)((*FUZZ_PARAM(unsigned int) % 512u) + 1u);
if (len <= 0) { FUZZ_BAIL(); }

// Prepare randomized, but size-consistent, buffers for inputs and output-in-place array.
// We use FUZZ_PARAM_STR once per buffer to avoid the macro's loop limitation.
std::string blob_types  = FUZZ_PARAM_STR();   // source bytes for bidi_types (4 bytes/elt preferred)
std::string blob_levels = FUZZ_PARAM_STR();   // source bytes for embedding_levels (1 byte/elt)
std::string blob_props  = FUZZ_PARAM_STR();   // source bytes for ar_props initialization (1 byte/elt)

if (blob_types.empty() || blob_levels.empty() || blob_props.empty()) { FUZZ_BAIL(); }

// Allocate arrays with exact len, enforcing API requirements that arrays are at least len long
std::vector<FriBidiCharType> bidi_types_vec((size_t)len, 0);
std::vector<FriBidiLevel> embedding_levels_vec((size_t)len, (FriBidiLevel)0);
std::vector<FriBidiArabicProp> ar_props_vec((size_t)len, (FriBidiArabicProp)0);

// Fill bidi_types with 32-bit values derived from blob_types bytes (wrap around if needed)
// FriBidiCharType is uint32_t in C++ builds; arbitrary class values are acceptable for exercising code paths
{
    const size_t sz = blob_types.size();
    for (size_t i = 0; i < (size_t)len; ++i) {
        // Combine up to 4 bytes to build a 32-bit value; wrap indices to stay within blob
        size_t b = (i * 4) % sz;
        uint32_t v = (uint32_t)(uint8_t)blob_types[b];
        v |= (uint32_t)((uint8_t)blob_types[(b + 1) % sz]) << 8;
        v |= (uint32_t)((uint8_t)blob_types[(b + 2) % sz]) << 16;
        v |= (uint32_t)((uint8_t)blob_types[(b + 3) % sz]) << 24;
        // Optionally constrain some bits to keep within typical bidi type mask domain
        // (no strict requirement, but reduces chance of hitting undefined internal masks)
        bidi_types_vec[i] = (FriBidiCharType)(v);
    }
}

// Fill embedding_levels with small valid levels (0..61). Even=>LTR, Odd=>RTL semantics are preserved by parity.
{
    const size_t sz = blob_levels.size();
    for (size_t i = 0; i < (size_t)len; ++i) {
        uint8_t b = (uint8_t)blob_levels[i % sz];
        FriBidiLevel lvl = (FriBidiLevel)(b % 62); // keep levels in a sensible small range
        embedding_levels_vec[i] = lvl;
    }
}

// Initialize ar_props with plausible joining property bytes. The API expects these to be
// pre-initialized (typically via fribidi_get_joining_types); random initialization is acceptable
// for fuzzing to exercise update logic without violating memory safety.
{
    const size_t sz = blob_props.size();
    for (size_t i = 0; i < (size_t)len; ++i) {
        ar_props_vec[i] = (FriBidiArabicProp)(uint8_t)blob_props[i % sz];
    }
}

// Sanity assertions about array sizes to strictly enforce preconditions
FUZZ_ASSERT(bidi_types_vec.size() >= (size_t)len, "bidi_types must have at least len entries");
FUZZ_ASSERT(embedding_levels_vec.size() >= (size_t)len, "embedding_levels must have at least len entries");
FUZZ_ASSERT(ar_props_vec.size() >= (size_t)len, "ar_props must have at least len entries");

// Invoke the target function. It updates ar_props_vec in place; there is no return status.
fribidi_join_arabic(
    (const FriBidiCharType*)bidi_types_vec.data(),
    len,
    (const FriBidiLevel*)embedding_levels_vec.data(),
    (FriBidiArabicProp*)ar_props_vec.data()
);

// Validation summary: This stub ensures all arrays are length-consistent and non-null, honoring API size
// requirements; ar_props is writable and updated in-place. No ownership is transferred; no outputs returned.

// Generate a valid Unicode scalar value for FriBidiChar (0..0x10FFFF, excluding UTF-16 surrogates)
unsigned int raw = *FUZZ_PARAM(unsigned int);
unsigned int cp = raw % 0x110000; // cap to max Unicode code point
if (cp >= 0xD800 && cp <= 0xDFFF) {
    // Remap surrogate range into non-surrogate BMP range to ensure a valid scalar value
    cp = 0xE000 + (cp - 0xD800); // results in [0xE000..0xE7FF]
}
FriBidiChar ch = (FriBidiChar)cp;

// Call the target function. It is pure and always returns a value.
volatile FriBidiCharType t = fribidi_get_bidi_type(ch);
(void)t; // prevent unused warning

// Validation summary:
// - Ensures input code point is a valid Unicode scalar value per API requirement.
// - No outputs to hand back; function is pure and returns by value.

// Pick a reasonable buffer length; keep allocations small for fuzzer perf
FriBidiStrIndex len = (FriBidiStrIndex)(*FUZZ_PARAM(unsigned int) % 257); // [0,256]

// Prepare input code points. Use FUZZ_PARAM_STR() as entropy and expand to Unicode scalars.
std::string entropy = FUZZ_PARAM_STR();
if (entropy.empty()) {
    // Ensure we have some bytes to derive from if len > 0
    entropy = "\x00";
}

std::vector<FriBidiChar> str_buf;
std::vector<FriBidiCharType> btypes_buf;
str_buf.reserve((size_t)len);
btypes_buf.resize((size_t)len);

// Fill str_buf with valid Unicode scalars derived from entropy bytes.
for (FriBidiStrIndex i = 0; i < len; ++i) {
    // Mix 4 bytes (wrapping over entropy as needed) into a 32-bit value
    unsigned int b0 = (unsigned char)entropy[(size_t)((i*4 + 0) % entropy.size())];
    unsigned int b1 = (unsigned char)entropy[(size_t)((i*4 + 1) % entropy.size())];
    unsigned int b2 = (unsigned char)entropy[(size_t)((i*4 + 2) % entropy.size())];
    unsigned int b3 = (unsigned char)entropy[(size_t)((i*4 + 3) % entropy.size())];
    unsigned int raw = (b0) | (b1 << 8) | (b2 << 16) | (b3 << 24);
    unsigned int cp = raw % 0x110000; // [0, 0x10FFFF]
    if (cp >= 0xD800 && cp <= 0xDFFF) {
        // Remap surrogate range into Private Use Area
        cp = 0xE000 + (cp - 0xD800); // [0xE000..0xE7FF]
    }
    str_buf.push_back((FriBidiChar)cp);
}

// Per API: if len > 0, pointers must be non-null and arrays sized >= len
const FriBidiChar *str_ptr = (len > 0) ? str_buf.data() : nullptr;
FriBidiCharType *btypes_ptr = (len > 0) ? btypes_buf.data() : nullptr;

// Invoke the target function; it writes len bidi types into btypes_ptr when len > 0
fribidi_get_bidi_types(str_ptr, len, btypes_ptr);

// Optional light-touch read to keep results live in optimized builds
if (len > 0) {
    volatile FriBidiCharType sink = btypes_buf[(size_t)(btypes_buf.size() - 1)];
    (void)sink;
}

// Validation summary:
// - Enforces len >= 0 and buffer non-nullness only when len > 0.
// - Ensures input characters are valid Unicode scalars to satisfy API expectations.
// - No persistent outputs are produced; buffers are local and correctly sized.

// Generate a FriBidiCharType value. In non-doc builds this is a 32-bit value; here we just fuzz it.
FriBidiCharType t = (FriBidiCharType)(*FUZZ_PARAM(unsigned int));

// Call the target function; it returns a static string (do not free/modify)
const char *name = fribidi_get_bidi_type_name(t);

// Be defensive: avoid dereferencing null; bail if unexpected null is returned
if (!name) { FUZZ_BAIL(); }

// Touch one byte to keep the value live
volatile char c0 = name[0];
(void)c0;

// Validation summary:
// - Uses arbitrary t; API promises a static const string for recognized values; we bail on null to avoid UB.
// - No outputs as the return is not an owned object and must not be freed.

// Generate a small logical string and derive bidi_types using FriBidi helpers.
// This ensures bidi_types/len invariants required by fribidi_get_par_direction.
std::string bytes = FUZZ_PARAM_STR();
// Cap length to keep allocations small and non-zero
FriBidiStrIndex len = (FriBidiStrIndex)bytes.size();
if (len <= 0) { len = 1; }
if (len > 128) { len = 128; }

// Build a FriBidiChar buffer from the random bytes (treat bytes as scalar values)
std::vector<FriBidiChar> logical_str((size_t)len);
for (FriBidiStrIndex i = 0; i < len; ++i) {
    logical_str[(size_t)i] = (unsigned char)bytes[(size_t)i];
}

