fribidi_get_bidi_types(logical_str.data(), len, bidi_types.data());

// Target call: compute paragraph direction for this paragraph's types
FriBidiParType par_dir = fribidi_get_par_direction(bidi_types.data(), len);

// The function only returns LTR, RTL, or ON; we cannot assert exact values here
// without pulling in the macro set, but a non-crashing call with valid buffers
// exercises the API. If future invariants fail, bail (none specified here).
(void)par_dir;

// Validation: Inputs were constructed to satisfy len/type requirements; no persistent outputs are produced.

// Build a single paragraph and compute bidi/bracket types per API requirements.
std::string bytes = FUZZ_PARAM_STR();
FriBidiStrIndex len = (FriBidiStrIndex)bytes.size();
if (len <= 0) { len = 1; }
if (len > 256) { len = 256; }

// Logical codepoint buffer from random bytes (kept small and non-zero length).
std::vector<FriBidiChar> logical_str((size_t)len);
for (FriBidiStrIndex i = 0; i < len; ++i) {
    logical_str[(size_t)i] = (unsigned char)bytes[(size_t)i];
}

