std::vector<FriBidiCharType> bidi_types((size_t)len);
fribidi_get_bidi_types(logical_str.data(), len, bidi_types.data());

// Derive bracket types; requires bidi_types for accuracy per API.
std::vector<FriBidiBracketType> bracket_types((size_t)len);
fribidi_get_bracket_types(logical_str.data(), len, bidi_types.data(), bracket_types.data());

// Provide requested base direction (ON/LTR/RTL) and receive the resolved base dir in-place.
unsigned req_sel = *FUZZ_PARAM(unsigned int) % 3u;
FriBidiParType base_req = (req_sel == 0 ? FRIBIDI_PAR_ON : (req_sel == 1 ? FRIBIDI_PAR_LTR : FRIBIDI_PAR_RTL));
FriBidiParType base_dir = base_req; // in/out as required by API

// Prepare output levels buffer (writable, sized to len).
std::vector<FriBidiLevel> embedding_levels((size_t)len);

// Target call.
FriBidiLevel max_level_plus_one = fribidi_get_par_embedding_levels_ex(
    bidi_types.data(),
    bracket_types.data(),
    len,
    &base_dir,
    embedding_levels.data()
);

// Per API, 0 indicates failure (e.g., allocation failure); bail in that case.
if (max_level_plus_one == 0) { FUZZ_BAIL(); }

// Property: on success max_level_plus_one >= 1.
FUZZ_ASSERT(max_level_plus_one >= 1, "max_level_plus_one must be >= 1 on success");

// Validation: All arrays are len elements, bracket_types derived with types, and pbase_dir non-null; no persistent outputs.

// Build a logical paragraph, compute required types and embedding levels,
// then reorder a valid line segment per API constraints.
std::string bytes = FUZZ_PARAM_STR();
FriBidiStrIndex para_len = (FriBidiStrIndex)bytes.size();
if (para_len <= 0) { para_len = 1; }
if (para_len > 256) { para_len = 256; }

std::vector<FriBidiChar> logical_str((size_t)para_len);
for (FriBidiStrIndex i = 0; i < para_len; ++i) {
    logical_str[(size_t)i] = (unsigned char)bytes[(size_t)i];
